{"script": "cat << 'EOF' > date_format.py
#!/usr/bin/env python3
import sys
from datetime import datetime

def main():
    if len(sys.argv) != 3:
        print("Usage: date-format <date_string> <format_string>")
        sys.exit(1)

    date_str = sys.argv[1]
    fmt_str = sys.argv[2]

    try:
        parts = date_str.split('-')
        if len(parts) == 3:
            year = int(parts[0])
            month = int(parts[1])
            day = int(parts[2])
            date_obj = datetime(year, month, day)
            sys.stdout.write(date_obj.strftime(fmt_str) + '\n')
        else:
            raise ValueError
    except Exception as e:
        sys.stderr.write(f"Error: {e}\n")
        sys.exit(1)

if __name__ == "__main__":
    main()
EOF
chmod +x date_format.py
sudo ln -sf $(pwd)/date_format.py /usr/local/bin/date-format
/usr/local/bin/date-format 2023-5-1 '%Y/%m/%d'
"}

